  "obj_knight_pointing_cone": {
    "name": "obj_knight_pointing_cone",
    "label": "Knight (Chapter 3) — obj_knight_pointing_cone",
    "create": "surf = -4;\nstarsurf = -4;\nangle = 0;\ntarget_angle = 60;\nbg_x = 0;\nlines_x = 0;\ntween = 0;\nease = 0;\nangle_lerp = 0;\nimage_xscale = 2;\nimage_yscale = 2;\nimage_speed = 0;\n\nif (i_ex(obj_knight_enemy))\n{\n    obj_knight_enemy.visible = false;\n    aetimer = obj_knight_enemy.aetimer;\n}\nelse\n{\n    aetimer = 0;\n}\n\ncon = 0;\ndifficulty = 0;\nyoff = irandom(60) + 2;\ntimer = 0;\nfake_gt = instance_create(x, y, obj_fake_gt);\ngt_x = obj_growtangle.x;\nknockback = 0;\nstar_flicker = 0;\ndraw_angle = 0;\nstarlist[0] = -1;\nchildlist[0] = -1;\npoint_frame = 0;\nafterimage_spread = 0;\nimage_timer = 0;\ntimerb = 0;\nendtimer = 120;\nchild_attack = false;\ncount = 0;\n",
    "step": "timerb++;\n\nif (timerb == 3)\n{\n    snd_play_x(snd_knight_drawpower, 1, 1.3);\n    snd_play_x(snd_knight_drawpower, 1, 1.3);\n    snd_play_x(snd_knight_drawpower, 1, 1.3);\n}\n\nif (timerb == 120)\n{\n    var a = 2;\n    var b = 0.7;\n    snd_play_x(snd_knight_star_explosion_close, a, b);\n    snd_play_x(snd_knight_star_explosion_close, a, b);\n    snd_play_x(snd_knight_star_explosion_close, a, b);\n}\n\nif (con == 4)\n{\n    x = lerp(x, obj_knight_enemy.x, 0.15);\n    y = lerp(y, obj_knight_enemy.y, 0.15);\n    \n    if (tween == 0)\n    {\n        con = 5;\n        \n        if (i_ex(obj_knight_enemy))\n        {\n            obj_knight_enemy.visible = true;\n            obj_knight_enemy.aetimer = aetimer;\n        }\n    }\n}\nelse if (tween < 1)\n{\n    tween = scr_movetowards(tween, 1, 0.05);\n    var _ease = scr_ease_out(tween, 4);\n    x = lerp(xstart, obj_growtangle.x + 115, _ease);\n    y = lerp(ystart, obj_growtangle.y - 56, _ease);\n}\n\nif (con < 2)\n{\n    exit;\n}\nelse if (global.turntimer <= endtimer)\n{\n    if (angle_lerp == 1)\n    {\n        var _count = 0;\n        \n        with (obj_knight_pointing_star)\n        {\n            other.starlist[_count] = self;\n            con = 1;\n            _count++;\n        }\n        \n        for (i = 0; i < _count; i++)\n        {\n            with (starlist[i])\n            {\n                timer = -other.i;\n                \n                if ((other.i % 2) == 1)\n                    playSound = false;\n            }\n        }\n        \n        knockback = 10;\n    }\n    \n    if (angle_lerp == 0 && con < 3)\n    {\n        timer = 10;\n        con = 3;\n        yoff = 120 + irandom_range(-60, 60);\n    }\n    \n    angle_lerp = scr_movetowards(angle_lerp, 0, 0.1);\n    angle = lerp(0, target_angle, scr_ease_in(angle_lerp, 6));\n}\nelse if (angle < target_angle)\n{\n    angle_lerp = scr_movetowards(angle_lerp, 1, 0.025);\n    angle = lerp(0, target_angle, scr_ease_out(angle_lerp, 6));\n}\nelse\n{\n    x += 0.25;\n}\n\nif (knockback != 0)\n{\n    var _knockback = scr_ease_in(knockback / 10, 5) * 10;\n    gt_x -= _knockback;\n    knockback = scr_movetowards(knockback, 0, 0.5);\n    fake_gt.xoffset = random_range(-1, 1) * (_knockback / 10);\n    fake_gt.yoffset = random_range(-1, 1) * (_knockback / 10);\n}\nelse\n{\n    gt_x -= (angle / target_angle / 2);\n    fake_gt.xoffset = random_range(-1, 1) * (angle / target_angle);\n    fake_gt.yoffset = random_range(-1, 1) * (angle / target_angle);\n}\n\nobj_growtangle.x = round(gt_x);\nobj_heart.x = min(obj_heart.x, gt_maxx() - 22);\n",
    "draw": "if (con >= 3)\n{\n    if (image_index == (image_number - 1))\n        image_index--;\n    else if (image_index > 0)\n        image_index -= 0.25;\n}\nelse if (image_index < (image_number - 1))\n{\n    image_index += 0.5;\n}\n\nif (con < 5)\n    draw_self();\n\naetimer++;\n\nif (con <= 4 && (aetimer % 4) == 0)\n{\n    var _after_image = scr_afterimage();\n    _after_image.image_alpha = 0.6;\n    _after_image.fadeSpeed = 0.02;\n    _after_image.speed = 2 + (afterimage_spread / 30);\n    _after_image.direction = (sin(aetimer) * angle) / 2;\n    _after_image.depth = obj_knight_enemy.depth + 1;\n    \n    if (con == 4)\n        afterimage_spread = scr_movetowards(afterimage_spread, 0, 20);\n    \n    if (con >= 1)\n        afterimage_spread++;\n}\n\nif (con >= 4)\n    exit;\n\nif (!surface_exists(surf))\n    surf = surface_create(640, 480);\n\nif (!surface_exists(starsurf))\n    starsurf = surface_create(640, 480);\n\nif (con <= 1)\n{\n    if (con == 0)\n        con = 1;\n    \n    if (timer < 28)\n    {\n        draw_set_blend_mode(bm_add);\n        draw_sprite_part_ext(spr_knight_bullet_flow, 2, timer * 1, ((timer * 4) + yoff) - 2, screenx(x + 22) / 2, 1, camerax(), y + 54, 2, 2, c_gray, 1);\n        \n        if ((timer % 2) == 0)\n            draw_sprite_part_ext(spr_knight_bullet_flow, 2, timer * 2, (timer * 4) + yoff, screenx(x + 22) / 2, 1, camerax(), y + 54, 2, 2, c_gray, 1);\n        \n        draw_set_blend_mode(bm_normal);\n    }\n    else\n    {\n        draw_set_color(c_white);\n        ossafe_fill_rectangle(camerax(), y + 54, x + 22, y + 56, false);\n    }\n    \n    timer++;\n    \n    if (timer >= 30)\n    {\n        snd_play_pitch(snd_rocket_long, 0.6);\n        con = 2;\n    }\n    \n    exit;\n}\n\nif (con == 3 && timer > 0)\n{\n    draw_set_blend_mode(bm_add);\n    draw_sprite_part_ext(spr_knight_bullet_flow, 2, (10 - timer) * 2, yoff - ((10 - timer) * 4), screenx(x + 22) / 2, 1, camerax(), y + 54, 2, 2, c_gray, timer / 10);\n    draw_sprite_part_ext(spr_knight_bullet_flow, 2, (10 - timer) * 2, yoff + ((10 - timer) * 4), screenx(x + 22) / 2, 1, camerax(), y + 54, 2, 2, c_gray, timer / 10);\n    timer--;\n    draw_set_blend_mode(bm_normal);\n    \n    if (timer == 0)\n        con = 4;\n    \n    exit;\n}\n\nsurface_set_target(surf);\ndraw_clear_alpha(c_black, 0);\ndraw_set_blend_mode(bm_normal);\ndraw_set_alpha(1);\ndraw_set_color(merge_color(c_white, c_black, angle / target_angle));\ndraw_primitive_begin(pr_trianglelist);\ndraw_angle = 1 - draw_angle;\nvar _angle = (angle > 0) ? (angle + draw_angle) : 0;\nvar _xleft = lengthdir_x(600, 180 + (_angle / 2));\nvar _ytop = lengthdir_y(600, 180 - (_angle / 2));\nvar _ybottom = lengthdir_y(600, 180 + (_angle / 2));\ndraw_vertex(screenx(x + 22) + _xleft, screeny(y + 56) + _ytop);\ndraw_vertex(screenx(x + 22), screeny(y + 56));\ndraw_vertex(screenx(x + 22) + _xleft, screeny(y + 58) + _ybottom);\ndraw_vertex(screenx(x + 22), screeny(y + 58));\ndraw_primitive_end();\ngpu_set_alphatestenable(true);\ngpu_set_blendmode_ext_sepalpha(bm_src_alpha, bm_one, bm_dest_alpha, bm_zero);\nvar _blend = 1;\ndraw_sprite_ext(spr_knight_bullet_flow, 0, bg_x, 0, 2, 2, 0, c_white, _blend);\ndraw_sprite_ext(spr_knight_bullet_flow, 0, bg_x + 640, 0, 2, 2, 0, c_white, _blend);\ndraw_sprite_ext(spr_knight_bullet_flow, 1, lines_x, 0, 2, 2, 0, c_white, _blend);\ndraw_sprite_ext(spr_knight_bullet_flow, 1, lines_x + 640, 0, 2, 2, 0, c_white, _blend);\nlines_x -= 80;\nbg_x -= 20;\n\nif (lines_x < -640)\n    lines_x += 640;\n\nif (bg_x < -640)\n    bg_x += 640;\n\ndraw_set_blend_mode(bm_subtract);\n\nwith (obj_heart)\n    draw_sprite(sprite_index, image_index, screenx(), screeny());\n\nif (instance_exists(obj_knight_pointing_star))\n{\n    surface_set_target(starsurf);\n    draw_set_blend_mode(bm_normal);\n    draw_clear_alpha(c_black, 0);\n    \n    with (obj_knight_pointing_star)\n    {\n        if (image_xscale > 0.5)\n            event_user(0);\n    }\n    \n    draw_set_blend_mode(bm_subtract);\n    draw_sprite_ext(spr_knight_line_grate, 0, 0, star_flicker, 2, 2, 0, c_black, 1);\n    star_flicker = 2 - star_flicker;\n    draw_set_blend_mode(bm_normal);\n    \n    with (obj_knight_pointing_star)\n    {\n        if (image_xscale <= 0.5)\n            event_user(0);\n    }\n    \n    surface_reset_target();\n    gpu_set_alphatestenable(true);\n    gpu_set_blendmode_ext_sepalpha(bm_src_alpha, bm_inv_src_alpha, bm_dest_alpha, bm_zero);\n    draw_surface(starsurf, 0, 0);\n}\n\ngpu_set_alphatestenable(false);\ndraw_set_blend_mode(bm_add);\nsurface_reset_target();\ndraw_surface(surf, camerax(), cameray());\ndraw_set_blend_mode(bm_normal);\n"
  },
