    "step": "timer++;\n\nif (con == 0)\n{\n    if (timer == 20)\n    {\n        timer = 0;\n        con = 1;\n        event_user(1);\n        snd_play_x(snd_knight_boxbreak, 1, 1.1);\n        snd_play(snd_chargeshot_fire);\n        instance_create(x, y, obj_knight_lightorb);\n        \n        if ((obj_heart.y + 10) < obj_growtangle.y)\n            heart_y = -1;\n        else\n            heart_y = 1;\n    }\n    \n    if (timer == 20 && false)\n    {\n        snd_play_x(snd_knight_boxbreak, 1, 1.1);\n        var _speed = 0;\n        var _balance_top = 0;\n        var _balance_bottom = 0;\n        var _change = 0;\n        event_user(0);\n        event_user(1);\n        \n        if ((obj_heart.y + 10) < obj_growtangle.y)\n            heart_y = -1;\n        else\n            heart_y = 1;\n        \n        snd_play(snd_chargeshot_fire);\n        var _xstart = obj_growtangle.x - 66;\n        var _b = -4;\n        \n        for (var _i = 0; _i < 14; _i++)\n        {\n            var _balance = ((_i % 2) == 0) ? _balance_top : _balance_bottom;\n            \n            if (_balance >= 3)\n                _change = -1;\n            else if (_balance <= -3)\n                _change = 1;\n            else\n                _change = choose(1, -1);\n            \n            _speed = _change ? 6 : 2.5;\n            \n            if ((_i % 2) == 0)\n                _balance_top += _change;\n            else\n                _balance_bottom += _change;\n            \n            var aa = choose(0, 1, 2, 3, 4, 5, 6);\n            var bb = choose(7, 8, 9, 10, 11, 12, 13);\n            _b = instance_create(_xstart, y, obj_roaringknight_fountain_bullet);\n            _b.speed = 0.01;\n            _b.top_speed = _speed + random_range(-0.1, 0.1);\n            _b.image_speed = _speed / 8;\n            _b.depth = depth + 1;\n            _b.image_xscale = 1;\n            _b.image_yscale = 1;\n            \n            if ((_i % 2) == 1)\n            {\n                _b.direction = -90;\n                _b.image_angle = 180;\n            }\n            else\n            {\n                _b.direction = 90;\n            }\n            \n            scr_bullet_inherit(_b);\n            child_bullet[count] = _b;\n            count++;\n            \n            if ((_i % 2) == 1)\n                _xstart += 22;\n        }\n    }\n}\n\nif (con == 1)\n{\n    if (timer == 7)\n    {\n        for (i = 0; i < count; i++)\n        {\n            if (i_ex(child_bullet[i]))\n                child_bullet[i].depth = obj_growtangle.depth - 10;\n        }\n    }\n    \n    if (timer <= 30)\n    {\n        var _old_distance = distance;\n        distance = scr_ease_out(timer / 30, 6) * 50;\n        obj_heart.y += ((distance - _old_distance) * heart_y * 1.25);\n    }\n    else\n    {\n        event_user(0);\n    }\n}\n\nvar _dist = round(distance);\nmarker[0].y = y - _dist - 1;\nmarker[1].y = y + _dist + 3;\n\nif (distance > 0)\n    obj_growtangle.x = -9999;\nelse\n    obj_growtangle.x = obj_growtangle.xstart;\n",
    "draw": "var _splid = 0;\nvar _dist = round(distance);\ndraw_sprite_part_ext_rot(sprite_index, 1, 0, 0, sprite_width, sprite_height / 2, x - _splid, y - _dist, image_xscale, image_yscale, 0, image_blend, 1);\ndraw_sprite_part_ext_rot(sprite_index, 1, 0, sprite_height / 2, sprite_width, sprite_height / 2, x + _splid, y + _dist, image_xscale, image_yscale, 0, image_blend, 1);\ndraw_sprite_part_ext_rot(sprite_index, 0, 0, 0, sprite_width, sprite_height / 2, x - _splid, y - _dist, image_xscale, image_yscale, 0, image_blend, 1);\ndraw_sprite_part_ext_rot(sprite_index, 0, 0, sprite_height / 2, sprite_width, sprite_height / 2, x + _splid, y + _dist, image_xscale, image_yscale, 0, image_blend, 1);\ndraw_set_color(c_white);\n\nif (_dist == 0)\n{\n    ossafe_fill_rectangle(x - 74 - _splid, y - _dist, (x + 75) - _splid, y - _dist, false);\n    ossafe_fill_rectangle((x - 74) + _splid, y + _dist, x + 75 + _splid, y + _dist, false);\n}\nelse\n{\n    draw_sprite_ext(spr_rk_split_flame_edge, flame_index, x + 2, y - _dist - 1, 2, 2, 180, c_gray, 1);\n    draw_sprite_ext(spr_rk_split_flame_edge, flame_index, x, y + _dist + 2, 2, 2, 0, c_gray, 1);\n}\n\nflame_index += 0.5;\n"
