    "step": "timer++;\n\nif (type == 0)\n{\n    var statetimer = 12;\n    \n    if (timer <= statetimer)\n    {\n        fakespeed = lerp(16, 4, timer / statetimer);\n        dirspeed = lerp(2.25, 1.5, timer / statetimer);\n    }\n    \n    if (timer > statetimer)\n    {\n        fakespeed = lerp(4, 16, (timer - statetimer) / statetimer);\n        dirspeed = lerp(1.5, 2.25, (timer - statetimer) / statetimer);\n    }\n    \n    if (timer > 24)\n        image_alpha -= 0.1;\n}\n\nif (type == 1)\n{\n    var statetimer = 12;\n    \n    if (timer <= statetimer)\n    {\n        fakespeed = lerp(14, 3, timer / statetimer);\n        dirspeed = lerp(3, 1.25, timer / statetimer);\n    }\n    \n    if (timer > statetimer)\n    {\n        fakespeed = lerp(3, 9, (timer - statetimer) / statetimer);\n        dirspeed = lerp(1.25, 1.75, (timer - statetimer) / statetimer);\n    }\n    \n    if (timer > 40)\n        image_alpha -= 0.1;\n}\n\nx = xstart + lengthdir_x(length, place);\ny = ystart + lengthdir_y(length, place);\nlength += fakespeed;\nplace += dirspeed;\n\nif (global.turntimer < 1)\n    instance_destroy();\n\nif (image_alpha < 0)\n    instance_destroy();\n\nif (x < (__view_get(e__VW.XView, 0) - 80))\n    instance_destroy();\n\nif (x > (__view_get(e__VW.XView, 0) + 760))\n    instance_destroy();\n\nif (y < (__view_get(e__VW.YView, 0) - 80))\n    instance_destroy();\n\nif (y > (__view_get(e__VW.YView, 0) + 580))\n    instance_destroy();\n\nenum e__VW\n{\n    XView,\n    YView,\n    WView,\n    HView,\n    Angle,\n    HBorder,\n    VBorder,\n    HSpeed,\n    VSpeed,\n    Object,\n    Visible,\n    XPort,\n    YPort,\n    WPort,\n    HPort,\n    Camera,\n    SurfaceID\n}\n",
    "draw": ""
