    "step": "timer++;\n\nif (y > (obj_growtangle.y + 120))\n    image_alpha -= 0.3;\n\nif (image_alpha < 0.8)\n    active = 0;\n\nif (y >= (scr_get_box(3) - 20) && !bounce)\n{\n    bounce = true;\n    me_flash = scr_oflash();\n    \n    with (me_flash)\n        target = other.id;\n    \n    snd_play_pitch(snd_metal_hit_reverb, 2);\n    y = scr_get_box(3) - 20;\n    vspeed = -20;\n    hspeed = 0;\n    gravity_direction = 270;\n    gravity = 1.2;\n}\n\nif (bounce)\n{\n    if ((timer % 2) == 0)\n        image_angle -= 40;\n}\nelse\n{\n    image_angle += 40;\n}\n\nif (!bounce)\n{\n    with (scr_afterimagefast())\n        fadeSpeed *= 3;\n}\n",
