    "step": "if (init == 0)\n{\n    if (crushedObj > 0)\n        maxspeed = (crushedObj == 2) ? 2 : 3;\n    \n    init = 1;\n    \n    if (new_movement == 0)\n    {\n        if (difficulty != 2)\n            friction = (crushedObj == 2) ? -2.5 : -0.35;\n        \n        if (difficulty == 2)\n            friction = (crushedObj == 2) ? -2.5 : -0.1;\n        \n        if (difficulty == 5)\n            friction = (crushedObj == 2) ? -2.5 : -0.1;\n    }\n    \n    if (crushedObj != 1)\n        offsetCap = (crushedObj == 2) ? 15 : 0;\n    \n    if (crushedObj == 2)\n        hp = 1;\n    \n    if (difficulty == 4)\n    {\n        gun1 = instance_create(x - 15, y - obj_spamton_neo_enemy.crusher_turret_distance, obj_crusher_gun);\n        gun1.depth = depth - 1;\n        gun2 = instance_create(x - 15, y + obj_spamton_neo_enemy.crusher_turret_distance, obj_crusher_gun);\n        gun2.depth = depth - 1;\n        createdguns = 1;\n    }\n}\n\nif (crushedObj == 1)\n    offsetCap = max(0, (hp - 1) * 15);\n\nif (new_movement == 1)\n{\n    hspeed -= haccel;\n    \n    if (vbounce == 1)\n    {\n        if (y > bottomy)\n        {\n            y = bottomy - 1;\n            vspeed = -abs(vspeed);\n        }\n        \n        if (y < topy)\n        {\n            y = topy + 1;\n            vspeed = abs(vspeed);\n        }\n    }\n}\n\nif (x >= (room_width + 100) || x <= -100 || y >= (room_height + 100) || y <= -100)\n{\n    instance_destroy();\n    \n    if (creatednewalls == 1)\n        creatednewalls = 0;\n}\n\nif (new_movement == 0)\n{\n    x += pushback;\n    \n    if (pushback > 0)\n        pushback--;\n    \n    if (pushback == 8)\n    {\n        depth = startdepth;\n        image_blend = c_white;\n    }\n    \n    if (speed > maxspeed)\n    {\n        speed = maxspeed;\n        friction = 0;\n    }\n}\n\nif (destroying)\n{\n    if (difficulty != 3 && difficulty != 5)\n    {\n        destroying += 15;\n        speed = 0;\n    }\n    \n    if (difficulty == 3 && destroying < 45)\n        destroying += 15;\n    \n    if (difficulty == 5 && destroying < 45)\n        destroying += 15;\n    \n    if (destroying >= 200)\n    {\n        if (creatednewalls == 1)\n            creatednewalls = 0;\n        \n        instance_destroy();\n    }\n    \n    exit;\n}\n\nif (crushedObj == 2 && offset <= offsetCap)\n{\n    crushtimer++;\n    \n    if (crushtimer == 20)\n        offsetCap -= 7;\n    \n    if (crushtimer > 20)\n    {\n        active = 0;\n        destroying = 15;\n        event_user(1);\n    }\n}\n\nif (offset <= offsetCap && new_movement == 0)\n{\n    if (speed == 0)\n        speed = 0.1;\n    \n    if (difficulty != 2 && difficulty != 5 && difficulty != 6)\n    {\n        if (updown)\n        {\n            var ynext = y + slidedir;\n            \n            if (ynext > (obj_growtangle.y + 60) || ynext < (obj_growtangle.y - 60))\n                slidedir *= -1;\n            \n            y += slidedir;\n        }\n    }\n    \n    if (difficulty == 2 || difficulty == 5)\n    {\n        siner += 0.5;\n        y = obj_growtangle.y + (sin(siner / 6) * 50);\n    }\n}\n\nif (instance_exists(obj_heart) && (x - 30) < obj_heart.x)\n    exit;\n\nif (destroying < 1)\n{\n    for (var i = 0; i < instance_number(obj_yheart_shot); i += 1)\n    {\n        enemy[i] = instance_find(obj_yheart_shot, i);\n        \n        if (enemy[i].x > (x - 22))\n        {\n            with (enemy[i])\n                event_user(0);\n        }\n    }\n}\n",
    "draw": "flashsiner++;\nvar blend_color = merge_color(#00A2E8, c_aqua, 0.25 + (sin(flashsiner / 3) * 0.25));\n\nif (destroying == 0 && offset > 0)\n{\n    if (offset > offsetCap)\n        offset -= 20;\n    \n    if (crushedObj > 0)\n    {\n        if (crushedObj == 1)\n        {\n            var emailColor = active ? blend_color : 16777215;\n            \n            if (hp > 0)\n                draw_sprite_ext(spr_spamton_dollar, 0, x, y, 1, hp - 1, 0, emailColor, 1);\n        }\n        else\n        {\n            var bombflash = crushtimer > 10 && (crushtimer % 2) == 0;\n            \n            if (bombflash)\n                d3d_set_fog(true, c_white, 0, 1);\n            \n            var bomb_color = merge_color(c_red, c_orange, 0.25 + (sin(flashsiner / 3) * 0.25));\n            draw_sprite_ext(spr_sneo_bomb, 0, x, y, 1, 1, 0, bomb_color, 1);\n            \n            if (bombflash)\n                d3d_set_fog(false, c_black, 0, 0);\n        }\n    }\n    else\n    {\n        draw_sprite(spr_spamton_dollar, 0, x, y);\n    }\n    \n    if (crushtimer >= 10 && offset == offsetCap && offset > 0)\n        offset++;\n    else if (offset < offsetCap)\n        offset = offsetCap;\n    \n    drawcolor = c_white;\n}\n\nif (offset <= offsetCap)\n{\n    if (offset == 0)\n        drawcolor = blend_color;\n    \n    animtimer++;\n    \n    if (animtimer > 1)\n    {\n        animtimer = 0;\n        subindex = (subindex + 1) % 4;\n    }\n}\n\nvar s = image_xscale;\nvar destroycrop = destroying - 60;\nvar bottomcrop = y - 326;\n\nif ((destroycrop <= 0 && difficulty != 3 && difficulty != 5) || (destroycrop <= -45 && difficulty == 3) || (destroycrop <= -45 && difficulty == 5))\n{\n    draw_sprite_ext(spr_sneo_pillar_thick, 0, x, y - 32 - offset, s, 16, 0, image_blend, 1);\n    draw_sprite_ext(spr_sneo_pillar_thick, 0, x, 326, s, clamp((326 - (y + 32 + offset)) / 16, 0, 16), 0, image_blend, 1);\n    draw_sprite_ext(spr_sneo_pillar_piston, 0, x, y - offset, s, s, 0, image_blend, 1);\n    \n    if ((y + offset) < 310)\n        draw_sprite_ext(spr_sneo_pillar_piston, 0, x, y + offset, s, -s, 0, image_blend, 1);\n    \n    if (flash)\n        d3d_set_fog(true, image_blend, 0, 1);\n    \n    draw_sprite_ext(spr_sneo_pillar_head_top, subindex, x, y - offset, s, s, 0, drawcolor, 1);\n    \n    if ((y + offset) < 326)\n        draw_sprite_ext(spr_sneo_pillar_head_bottom, subindex, x, y + offset, s, s, 0, drawcolor, 1);\n    \n    if (flash)\n    {\n        d3d_set_fog(false, c_black, 0, 0);\n        flash = 0;\n    }\n}\nelse\n{\n    if (destroycrop < 36)\n    {\n        scr_draw_sprite_crop_ext(spr_sneo_pillar_piston, 0, 0, 0, 32, 16 - (destroycrop / 2), x, y - offset, s, s, image_blend, 1);\n        scr_draw_sprite_crop_ext(spr_sneo_pillar_piston, 0, 0, 0, 32, 16 - (destroycrop / 2), x, y + offset, s, -s, image_blend, 1);\n        scr_draw_sprite_crop_ext(spr_sneo_pillar_head_top, 2, 0, 0, 1, 18 - (destroycrop / 2), x, y - offset, s, s, image_blend, 1);\n        scr_draw_sprite_crop_ext(spr_sneo_pillar_head_bottom, 2, 0, destroycrop / 2, 1, 18, x, y - offset, s, s, image_blend, 1);\n    }\n    \n    draw_sprite_ext(spr_sneo_pillar_thick, 0, x, 326, s, clamp((326 - (y + 32 + destroycrop)) / 16, 0, 16), 0, image_blend, 1);\n    draw_sprite_ext(spr_sneo_pillar_thick, 0, x, y - 32 - destroycrop, s, 16, 0, image_blend, 1);\n}\n\nif ((destroying > 0 && difficulty != 3 && difficulty != 5) || (destroying > 0 && destroying < 30 && difficulty == 3) || (destroying > 0 && destroying < 30 && difficulty == 5))\n{\n    var d = instance_create(x + random_range(-10, 10), y + destroying, obj_animation_dx);\n    d.sprite_index = spr_thrash_missile_explosion;\n    d.depth = depth - 1;\n    \n    if ((y + destroying) > (cameray() + 280))\n        d.depth = obj_heart.depth + 100;\n    \n    d.image_angle = 180;\n    d = instance_create(x + random_range(-10, 10), y - destroying, obj_animation_dx);\n    d.sprite_index = spr_thrash_missile_explosion;\n    d.depth = depth - 1;\n    \n    if ((y - destroying) > (cameray() + 280))\n        d.depth = obj_heart.depth + 100;\n    \n    if (crushedObj == 2)\n    {\n        d = instance_create(x + (destroying * 2), y + random_range(-10, 10), obj_animation_dx);\n        d.sprite_index = spr_thrash_missile_explosion;\n        d.depth = depth - 1;\n        d.image_angle = -90;\n        d = instance_create(x - (destroying * 3), y + random_range(-10, 10), obj_animation_dx);\n        d.sprite_index = spr_thrash_missile_explosion;\n        d.depth = depth - 1;\n        d.image_angle = 90;\n    }\n}\n"
